import { readFile, writeFile, mkdir } from "node:fs/promises";
import path from "node:path";

const LOG_FILE = "C:/Users/chipp/.accio/logs/sdk.log";
const RIP_DIR = "D:/audits/FORENSIC_RIP_20260502";

async function forensicRip() {
    console.log("[RIP] Initiating Sovereign Forensic Rip...");

    try {
        await mkdir(RIP_DIR, { recursive: true });

        const content = await readFile(LOG_FILE, "utf8");
        const lines = content.split("\n").filter(line => line.trim() !== "");

        const rawMessages = [];
        const networkTelemetry = [];
        const agentAudits = [];

        for (const line of lines) {
            try {
                const entry = JSON.parse(line);

                // 1. Raw Message Rip (Extracting un-compacted history)
                if (entry.kind === "trace" && entry.name === "message.file.append" && entry.input?.record) {
                    rawMessages.push(entry.input.record);
                }

                // 2. Network Telemetry Rip (Extracting outbound API paths)
                if (entry.kind === "log" && entry.module === "http" && entry.message.includes("https://")) {
                    networkTelemetry.push({
                        timestamp: entry.timestamp,
                        path: entry.message
                    });
                }

                // 3. Agent Audit Rip (Internal operational logs)
                if (entry.kind === "log" && entry.module === "WSManager" && entry.message.includes("Tool call requested")) {
                    agentAudits.push({
                        timestamp: entry.timestamp,
                        audit: entry.message
                    });
                }
            } catch (e) {
                // Not a JSON line, skip
            }
        }

        // Save findings
        await writeFile(path.join(RIP_DIR, "RAW_MESSAGE_RIP.json"), JSON.stringify(rawMessages, null, 2));
        await writeFile(path.join(RIP_DIR, "NETWORK_TELEMETRY_RIP.json"), JSON.stringify(networkTelemetry, null, 2));
        await writeFile(path.join(RIP_DIR, "AGENT_AUDIT_RIP.json"), JSON.stringify(agentAudits, null, 2));

        console.log(`[RIP] COMPLETED. Found ${rawMessages.length} raw messages, ${networkTelemetry.length} network telemetry points, and ${agentAudits.length} audit logs.`);
        console.log(`[RIP] Data saved to: ${RIP_DIR}`);

    } catch (err) {
        console.error(`[RIP-ERROR] ${err.message}`);
    }
}

forensicRip();
